package app.noir.mobile;
import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;

public final class ProfilesActivity extends Activity {
    static final String[] COLORS={"#E4C084","#7AA7FF","#E5707A","#7BD88F","#B58CFF","#F0A35E","#5FD0C9"};
    static {String[][] words={{"Phone profiles","ملفات الهاتف"},{"Edit","تعديل"},{"Linked to %s on your PC","مرتبط بـ %s على جهازك"},{"Each profile keeps its own history, lists and settings. Link one to a PC profile to sync both ways.","لكل ملف سجله وقوائمه وإعداداته. اربطه بملف على الكمبيوتر للمزامنة في الاتجاهين."},{"Only on this phone","على هذا الهاتف فقط"},{"+ New profile","+ ملف جديد"},{"Link to PC profile…","ربط بملف على الكمبيوتر…"},{"Create on PC","إنشاء على الكمبيوتر"},{"Profile name","اسم الملف"},{"Local PIN (leave empty to remove)","رمز محلي (اتركه فارغًا لإزالته)"},{"Enter PIN","أدخل الرمز"},{"That PIN isn't right.","الرمز غير صحيح."},{"Delete this phone profile?","حذف ملف الهاتف هذا؟"},{"Switch to another profile before deleting this one.","انتقل إلى ملف آخر قبل حذف هذا الملف."},{"Pair with your PC first.","اقترن بالكمبيوتر أولاً."},{"PC is unreachable. Your changes are saved on this phone.","الكمبيوتر غير متاح. تغييراتك محفوظة على هذا الهاتف."},{"Downloads are pausing. Try again in a moment.","جارٍ إيقاف التنزيلات مؤقتًا. حاول بعد لحظة."},{"Create another phone profile to link a different PC profile.","أنشئ ملف هاتف آخر لربطه بملف كمبيوتر مختلف."},{"Choose a name and color","اختر اسمًا ولونًا"},{"Save","حفظ"},{"Cancel","إلغاء"},{"Delete","حذف"},{"Edit profile","تعديل الملف"},{"Keep existing PIN","الاحتفاظ بالرمز الحالي"},{"Too many PIN attempts. Try again in five minutes.","محاولات رمز كثيرة. حاول بعد خمس دقائق."}};for(String[] pair:words)Loc.AR.put(pair[0],pair[1]);}
    static {Loc.AR.put("Delete profile and downloads","حذف الملف والتنزيلات");Loc.AR.put("Downloads on this phone: %s. Deleting the profile also deletes these copies. Cancel to keep them.","التنزيلات على هذا الهاتف: %s. حذف الملف يحذف هذه النسخ أيضًا. ألغِ العملية للاحتفاظ بها.");}
    static void confirmDelete(Activity a,ProfileStore profiles,String id,Runnable done){DataStore worker=NoirApp.data;worker.network.execute(()->{try{long bytes=profiles.downloadBytes(id);String size=android.text.format.Formatter.formatFileSize(a,bytes);a.runOnUiThread(()->{if(a.isFinishing()||a.isDestroyed())return;new AlertDialog.Builder(a).setTitle(Loc.t("Delete this phone profile?")).setMessage(Loc.f("Downloads on this phone: %s. Deleting the profile also deletes these copies. Cancel to keep them.",size)).setPositiveButton(Loc.t("Delete profile and downloads"),(d,w)->worker.network.execute(()->{try{profiles.delete(id,true);a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())done.run();});}catch(Exception e){a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())new AlertDialog.Builder(a).setMessage(Loc.t(e.getMessage())).setPositiveButton(Loc.t("OK"),null).show();});}})).setNegativeButton(Loc.t("Cancel"),null).show();});}catch(Exception e){a.runOnUiThread(()->{if(!a.isFinishing()&&!a.isDestroyed())new AlertDialog.Builder(a).setMessage(Loc.t(e.getMessage())).setPositiveButton(Loc.t("OK"),null).show();});}});}
    ProfileStore profiles;LinearLayout body;final android.os.Handler ui=new android.os.Handler(android.os.Looper.getMainLooper());
    @Override public void onCreate(Bundle b){super.onCreate(b);profiles=new ProfileStore(this);getWindow().setStatusBarColor(Color.rgb(11,11,13));getWindow().setNavigationBarColor(Color.rgb(11,11,13));render();Loc.apply(this);}
    String t(String s){return Loc.t(s);}
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView text(String value,int size){TextView v=new TextView(this);v.setText(t(value));v.setTextColor(Color.rgb(244,241,235));v.setTextSize(size);v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}
    Button button(String value,Runnable click){return button(value,click,false);}
    // Rounded like the rest of the app; the primary action is gold.
    Button button(String value,Runnable click,boolean primary){Button v=new Button(this);v.setText(t(value));v.setTextColor(primary?Color.rgb(22,18,12):Color.rgb(244,241,235));v.setTextSize(16);v.setAllCaps(false);v.setStateListAnimator(null);v.setBackground(MainActivity.bg(primary?MainActivity.GOLD:Color.rgb(31,31,35),dp(18)));v.setPadding(dp(18),dp(14),dp(18),dp(14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));v.setLayoutParams(lp);v.setOnClickListener(w->click.run());Motion.card(v);return v;}
    void render(){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Color.rgb(11,11,13));body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(20),dp(16),dp(24));scroll.addView(body);setContentView(scroll);Button back=button("‹ Back",this::finish);back.setBackground(null);back.setTextColor(MainActivity.GOLD);back.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);back.setPadding(dp(4),dp(8),dp(4),dp(8));body.addView(back,new LinearLayout.LayoutParams(-2,-2));TextView title=text("Phone profiles",30);title.setTypeface(null,android.graphics.Typeface.BOLD);body.addView(title);body.addView(text("Each profile keeps its own history, lists and settings. Link one to a PC profile to sync both ways.",13));
        for(JSONObject p:DataStore.objects(profiles.list())){String id=p.optString("id");LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),dp(12),dp(8),dp(12));TextView avatar=text(p.optString("name","?").substring(0,1).toUpperCase(java.util.Locale.getDefault()),24);avatar.setGravity(Gravity.CENTER);GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(Color.parseColor(p.optString("color")));avatar.setTextColor(Color.rgb(22,18,12));avatar.setBackground(circle);row.addView(avatar,new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout lines=new LinearLayout(this);lines.setOrientation(LinearLayout.VERTICAL);lines.addView(text(p.optString("name")+(p.optString("pinHash").isEmpty()?"":"  🔒")+(id.equals(profiles.current())?"  ✓":""),18));lines.addView(text(p.optString("pcProfileId","").isEmpty()?t("Only on this phone"):Loc.f("Linked to %s on your PC",p.optString("pcProfileName")),12));row.addView(lines,new LinearLayout.LayoutParams(0,-2,1));row.setContentDescription(p.optString("name"));row.setOnClickListener(v->authenticate(id,pin->work(()->{NoirApp.switchProfile(this,id,pin);ui.post(()->{startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();});})));row.setOnLongClickListener(v->{authenticate(id,pin->edit(p));return true;});Button editButton=button("Edit",()->authenticate(id,pin->edit(p)));editButton.setLayoutParams(new LinearLayout.LayoutParams(-2,-2));row.addView(editButton);row.setBackground(MainActivity.bg(id.equals(profiles.current())?Color.rgb(36,31,25):Color.rgb(24,24,27),dp(22)));row.setPadding(dp(14),dp(14),dp(14),dp(14));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.setMargins(0,dp(8),0,dp(8));Motion.card(row);body.addView(row,rp);}
        body.addView(button("+ New profile",()->edit(null),true));body.addView(button("Link to PC profile…",this::choosePc));body.addView(button("Create on PC",this::createPc));body.addView(text(NoirApp.data.lastSyncState(),12));}
    interface PinAction{void run(String pin);}
    void authenticate(String id,PinAction action){if(profiles.get(id).optString("pinHash").isEmpty()){action.run("");return;}EditText field=input("Enter PIN");field.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(t("Enter PIN")).setView(field).setPositiveButton(t("Open"),null).setNegativeButton(t("Cancel"),null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->work(()->{if(!profiles.checkPin(id,field.getText().toString()))throw new IllegalArgumentException(t("That PIN isn't right."));ui.post(()->{dialog.dismiss();action.run(field.getText().toString());});})));dialog.show();}
    EditText input(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(t(hint));e.setTextColor(Color.rgb(244,241,235));return e;}
    void edit(JSONObject profile){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(20),dp(8),dp(20),dp(8));EditText name=input("Profile name");name.setText(profile==null?"":profile.optString("name"));form.addView(name);Spinner colors=new Spinner(this);colors.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,COLORS));for(int n=0;profile!=null&&n<COLORS.length;n++)if(COLORS[n].equalsIgnoreCase(profile.optString("color")))colors.setSelection(n);form.addView(colors);CheckBox keep=new CheckBox(this);keep.setText(t("Keep existing PIN"));keep.setTextColor(Color.WHITE);keep.setChecked(profile!=null&&!profile.optString("pinHash").isEmpty());form.addView(keep);EditText pin=input("Local PIN (leave empty to remove)");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);form.addView(pin);
        AlertDialog.Builder builder=new AlertDialog.Builder(this).setTitle(t(profile==null?"+ New profile":"Edit profile")).setView(form).setPositiveButton(t("Save"),null).setNegativeButton(t("Cancel"),null);if(profile!=null)builder.setNeutralButton(t("Delete"),(d,w)->confirmDelete(this,profiles,profile.optString("id"),this::render));AlertDialog dialog=builder.create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->work(()->{String color=COLORS[colors.getSelectedItemPosition()];JSONObject p=profile==null?profiles.create(name.getText().toString(),color):profile;String id=p.optString("id");profiles.rename(id,name.getText().toString(),color);if(!keep.isChecked()||pin.length()>0)profiles.pin(id,pin.getText().toString());if(!p.optString("pcProfileId","").isEmpty()){DataStore data=id.equals(NoirApp.data.profileId)?NoirApp.data:NoirApp.dataFor(this,id);data.renameLinkedProfile(name.getText().toString(),color);data.syncSoon();}ui.post(()->{dialog.dismiss();render();});})));dialog.show();}
    void choosePc(){DataStore data=NoirApp.data;if(!data.paired()){message(t("Pair with your PC first."));return;}work(()->{JSONArray list=data.pcRequest("/v1/profiles",null).optJSONArray("profiles");ui.post(()->{java.util.List<JSONObject> rows=DataStore.objects(list);String[] names=new String[rows.size()];for(int n=0;n<rows.size();n++)names[n]=rows.get(n).optString("name")+(rows.get(n).optBoolean("locked")?"  🔒":"");new AlertDialog.Builder(this).setTitle(t("Link to PC profile…")).setItems(names,(d,n)->{JSONObject p=rows.get(n);String linked=data.linkedProfile();if(!linked.isEmpty()&&!linked.equals(p.optString("id"))){message(t("Create another phone profile to link a different PC profile."));return;}if(p.optBoolean("locked")){EditText pin=input("Enter PIN");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);new AlertDialog.Builder(this).setTitle(t("Enter PIN")).setView(pin).setPositiveButton(t("Open"),(x,y)->link(data,p,pin.getText().toString())).setNegativeButton(t("Cancel"),null).show();}else link(data,p,null);}).show();});});}
    void link(DataStore data,JSONObject p,String pin){work(()->{if(pin!=null){JSONObject request=new JSONObject();DataStore.put(request,"pin",pin);data.pcRequest("/v1/profiles/"+p.optString("id")+"/unlock",request);}profiles.link(data.profileId,p.optString("id"),p.optString("name"),p.optString("color"),p.optString("hostId"));try{data.sync();}finally{ui.post(this::render);}});}
    void createPc(){if(!NoirApp.data.linkedProfile().isEmpty()){message(t("Create another phone profile to link a different PC profile."));return;}EditText name=input("Profile name");name.setText(profiles.get(profiles.current()).optString("name"));new AlertDialog.Builder(this).setTitle(t("Create on PC")).setView(name).setPositiveButton(t("Create on PC"),(d,w)->work(()->{DataStore data=NoirApp.data;JSONObject request=new JSONObject();DataStore.put(request,"name",name.getText().toString());DataStore.put(request,"color",profiles.get(data.profileId).optString("color"));JSONObject p=data.pcRequest("/v1/profiles",request);profiles.link(data.profileId,p.optString("id"),p.optString("name"),p.optString("color"),p.optString("hostId"));try{data.sync();}finally{ui.post(this::render);}})).setNegativeButton(t("Cancel"),null).show();}
    interface Work{void run()throws Exception;}
    void work(Work action){NoirApp.data.network.execute(()->{try{action.run();}catch(Exception e){ui.post(()->message(e instanceof java.net.ConnectException||e instanceof java.net.SocketTimeoutException?t("PC is unreachable. Your changes are saved on this phone."):e.getMessage()));}});}
    void message(String message){if(!isFinishing())new AlertDialog.Builder(this).setMessage(t(message)).setPositiveButton(t("OK"),null).show();}
}
